-- Mob inserts from 魔兽图鉴
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-001', '焰尾蜥', '魔兽', 6, 4, 7, 5, '火', '【外观】体表覆盖赤红色鳞片，背部有火焰纹路，尾巴末端常年燃烧着拳头大小的橘红色火焰。
【体型】体长1.2米，肩高0.4米
【核心能力】尾焰喷射：甩尾时能喷出短程火球，射程约3米，点燃干草和木质物品。
【弱点】水属性攻击可瞬间熄灭其尾焰，失去核心能力后战力大减。', '[{"item_id": "mh-h1-1", "name": "一阶火属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-116", "name": "【ID】mh-h1-1 一阶火属性魔核-劣质，呈暗红色，可用于低级火焰符文的铭刻。，【ID】cl-100 焰鳞片（制作低阶火抗护甲的材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-002', '霜纹蛙', '魔兽', 6, 4, 7, 5, '冰', '【外观】通体冰蓝色，背部有白色霜状纹理，眼睛凸出呈淡蓝色，皮肤表面常年凝结薄霜。
【体型】体长0.3米，肩高0.15米
【核心能力】冰息吐息：从口中喷出寒冷雾气，能使小范围地面结霜，减缓敌人移动速度。
【弱点】火属性攻击能快速融化其体表冰霜，使其体温失衡陷入虚弱。', '[{"item_id": "mh-h1-5", "name": "一阶冰属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-112", "name": "【ID】mh-b1-1 一阶冰属性魔核-劣质，呈透明蓝色，可用于制作低级冰系药剂。，【ID】cl-101 冰蛙皮（可制成清凉布料，夏季衣物材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-003', '风翎雀', '魔兽', 6, 4, 7, 5, '风', '【外观】羽毛呈青灰色，翅膀边缘有淡绿色翎羽，飞行时翼尖会留下微弱的气流轨迹。
【体型】体长0.25米，翼展0.6米
【核心能力】风刃：振翅时能刮出三道无形的微风刃，割伤对手皮肤，有效距离5米。
【弱点】雷属性攻击能干扰其羽毛上的气流，使其失去平衡无法飞行。', '[{"item_id": "mh-h1-3", "name": "一阶风属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-114", "name": "【ID】mh-f1-1 一阶风属性魔核-劣质，呈浅绿色，可用于低级风系淬炼。，【ID】cl-102 风翎羽（制作轻身符咒的材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-004', '岩甲龟', '魔兽', 6, 4, 7, 5, '土', '【外观】龟壳呈深褐色，表面布满不规则的岩石凸起，四肢粗壮覆盖角质鳞片，头部扁平。
【体型】壳长0.8米，壳高0.3米
【核心能力】岩壳防御：遇敌时四肢和头部缩入壳内，龟壳硬度堪比普通岩石，可抵御低阶兵刃劈砍。
【弱点】连续重击或土属性以外的斗气渗透能震裂龟壳，冰系冻结后更易碎裂。', '[{"item_id": "mh-h1-6", "name": "一阶土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-120", "name": "【ID】mh-t1-1 一阶土属性魔核-劣质，呈黄褐色，可用于低级炼器材料。，【ID】cl-103 岩甲壳碎片（适合打磨成低级护甲片）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-005', '电纹鼠', '魔兽', 6, 4, 7, 5, '雷', '【外观】体毛呈灰黑色，背部有三条淡黄色闪电状条纹，尾巴细长且末端膨大如球，耳廓圆润。
【体型】体长0.2米，肩高0.1米
【核心能力】电击球：尾巴末端聚集雷电能量，射出拳头大小的电球，击中目标后产生麻痹效果，持续数息。
【弱点】地面潮湿时其电击会传导到自身，造成反噬；土属性攻击能有效压制其雷电。', '[{"item_id": "mh-h1-4", "name": "一阶雷属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-117", "name": "【ID】mh-l1-2 一阶雷属性魔核-普通，呈淡黄色，可用于低级雷电符咒。，【ID】cl-104 电纹鼠尾（可研磨成麻痹药粉）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-006', '黑雾蝮', '魔兽', 6, 4, 7, 5, '暗', '【外观】蛇身通体漆黑，鳞片之间有暗紫色雾气渗出，头部呈三角形，眼睛为浑浊的灰色。
【体型】体长1.5米，身体直径0.1米
【核心能力】暗雾喷射：从口中喷出浓稠的黑色雾气，遮蔽视野并带有微弱腐蚀性，能灼伤皮肤。
【弱点】光明类斗技或火属性爆炸产生的强光能驱散暗雾，使其失去遮蔽优势。', '[{"item_id": "mh-h1-9", "name": "一阶暗属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-111", "name": "【ID】mh-a1-2 一阶暗属性魔核-普通，呈深紫色，可用于低级暗系淬炼。，【ID】cl-105 黑雾蝮毒牙（可提炼成麻痹毒液）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-007', '毒棘蜂', '魔兽', 6, 4, 7, 5, '毒', '【外观】身体黄黑相间，腹部末端有粗大的黑色毒刺，翅膀半透明带有绿色纹路，复眼呈暗红色。
【体型】体长0.15米，翼展0.3米
【核心能力】毒刺穿刺：尾部毒刺可刺入皮肤注入神经毒素，使中毒部位麻木、肿胀，严重时可短暂瘫痪。
【弱点】火焰能烧毁其翅膀，冰系攻击能冻结其腹部毒囊，减少毒素活性。', '[{"item_id": "mh-h1-10", "name": "一阶毒属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-113", "name": "【ID】mh-d1-1 一阶毒属性魔核-劣质，呈绿色，可用于低级毒剂调配。，【ID】cl-106 毒棘蜂刺（制作低级淬毒暗器的材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-008', '青木獾', '魔兽', 6, 4, 7, 5, '木', '【外观】体毛为深棕色，背部覆盖一层青绿色苔藓状物质，四肢短粗，爪子呈木质化褐色，鼻尖湿润。
【体型】体长0.6米，肩高0.3米
【核心能力】藤蔓缠绕：前爪拍击地面时，能从周围泥土中催生出柔韧的藤蔓，缠绕敌人脚踝，持续约十息。
【弱点】火属性攻击能烧毁其催生的藤蔓，且木属性斗技可与之共鸣反制。', '[{"item_id": "mh-h1-7", "name": "一阶木属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-118", "name": "【ID】mh-m1-1 一阶木属性魔核-劣质，呈翠绿色，可用于低级木系药剂的培养。，【ID】cl-107 青木獾爪（可制成低阶木系法杖的镶嵌物）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-009', '水纹鳄', '魔兽', 6, 4, 7, 5, '水', '【外观】体表覆盖深绿色鳞甲，背部有三道浅蓝色波浪纹路，嘴巴宽阔，利齿密布，尾巴扁平有力。
【体型】体长2米，肩高0.5米
【核心能力】水弹连射：张口凝聚水属性斗气，连续喷出拳头大小的水弹，射程8米，冲击力足以击碎木板。
【弱点】雷属性攻击在水中传导会加倍伤害，且冰系能冻结其活动水域。', '[{"item_id": "mh-h1-2", "name": "一阶水属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-119", "name": "【ID】mh-s1-2 一阶水属性魔核-普通，呈淡蓝色，可用于低级水系斗技的辅助。，【ID】cl-108 水纹鳄皮（制作低级水抗护甲的主要材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-010', '烈阳蝶', '魔兽', 6, 4, 7, 5, '火', '【外观】翅膀呈火焰般的橙红色，带有黑色斑点，翅膀边缘有细小的火焰微粒飘散，飞行时留下淡淡火星轨迹。
【体型】翼展0.3米，体长0.1米
【核心能力】火星散播：振翅时散落细小火星，能引燃干燥的草木，造成小范围火灾。
【弱点】大量水分或水属性斗技可迅速扑灭其火星，翅膀沾水后难以飞行。', '[{"item_id": "mh-h1-1", "name": "一阶火属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-115", "name": "【ID】mh-h1 一阶火属性魔核，呈橘红色，体积小但纯度高，可用于低级附魔。，【ID】cl-109 烈阳蝶鳞粉（低级引火药的原料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-011', '霜角鹿', '魔兽', 6, 4, 7, 5, '冰', '【外观】体毛雪白，鹿角呈半透明的冰蓝色，角尖凝结着白霜，眼睛为淡蓝色，蹄子宽大适应雪地。
【体型】体长1.5米，肩高1米
【核心能力】冰角冲撞：低头冲锋时，鹿角会凝结冰层，撞击后产生冻伤效果，使伤口难以愈合。
【弱点】火属性斗技可融化其冰角，使其失去主要攻击手段。', '[{"item_id": "mh-h1-5", "name": "一阶冰属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-570", "name": "霜角粉末（可制成低级冰系止血药粉）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-012', '沙蝎', '魔兽', 6, 4, 7, 5, '土', '【外观】外壳呈黄褐色，背甲粗糙如同沙砾，尾钩弯曲尖锐呈黑色，螯钳粗壮有力，复眼细小。
【体型】体长0.5米，肩高0.2米
【核心能力】砂石突刺：钳子挥击地面时，能从沙中激射出数枚尖锐的砂石碎片，覆盖前方两米扇形区域。
【弱点】水属性攻击能使其沙壳软化变重，行动迟缓；冰系冻结后外壳脆化。', '[{"item_id": "mh-h1-6", "name": "一阶土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-340", "name": "沙蝎尾钩（可制成低阶穿刺武器）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-013', '风刃螳', '魔兽', 6, 4, 7, 5, '风', '【外观】身体翠绿色，前肢呈镰刀状且边缘锋利如刃，翅膀薄如蝉翼，头部三角形，复眼金黄色。
【体型】体长0.4米，前肢长0.3米
【核心能力】风刃斩击：挥动前肢时产生无形的风刃，能切断小树枝和布匹，近战攻击距离可达1.5米。
【弱点】雷属性斗技可以干扰其翅膀振动，使其失去平衡；重甲防御可抵挡风刃。', '[{"item_id": "mh-h1-3", "name": "一阶风属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-587", "name": "风刃螳前肢（可打磨成低阶匕首）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-014', '雷纹豹', '魔兽', 6, 4, 7, 5, '雷', '【外观】体毛呈灰黄色，全身布满黑色闪电状斑纹，肌肉线条流畅，尾巴末端有微弱电光闪烁。
【体型】体长1.8米，肩高0.8米
【核心能力】雷爪：利爪挥击时带有电光，击中目标后产生麻痹效果，可短暂僵直对手。
【弱点】水属性环境会使雷爪的能量扩散到全身，造成自伤；土属性攻击可震散其雷电。', '[{"item_id": "mh-h1-4", "name": "一阶雷属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-545", "name": "雷纹豹爪（适合制作带麻痹效果的短兵器）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-015', '暗影蝠', '魔兽', 6, 4, 7, 5, '暗', '【外观】身体覆盖暗灰色绒毛，翅膀膜呈半透明的暗紫色，耳朵尖长，眼睛在暗处发出模糊的红光。
【体型】翼展0.8米，体长0.2米
【核心能力】暗影声波：发出人耳听不到的声波，在黑暗中精准定位猎物，同时声波带有微弱的精神干扰，使人头晕目眩。
【弱点】强光能致盲其暗适应能力，火属性爆炸产生的巨响能震伤其听觉系统。', '[{"item_id": "mh-h1-9", "name": "一阶暗属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-232", "name": "暗影蝠翼膜（可制成低级隔音材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-016', '毒雾菇精', '魔兽', 6, 4, 7, 5, '毒', '【外观】形似一朵巨大的蘑菇，伞盖呈暗绿色带有黄斑，伞柄粗壮，伞盖下散发淡绿色毒雾，有两只小眼睛。
【体型】伞盖直径0.5米，高0.6米
【核心能力】毒雾弥漫：从伞盖下持续释放淡绿色的有毒雾气，范围可达三米，吸入后喉咙灼痛、视线模糊。
【弱点】火属性燃烧能快速烧尽毒雾，风属性吹拂可驱散毒雾使其暴露本体。', '[{"item_id": "mh-h1-10", "name": "一阶毒属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-312", "name": "毒雾菇伞盖（可晒干磨粉制成低级毒粉）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-017', '木甲熊', '魔兽', 6, 4, 7, 5, '木', '【外观】体型壮硕，体表覆盖一层木质化的甲片，呈深褐色，背部长有粗大的树枝状角，爪子像树根一样扭曲。
【体型】体长2.5米，肩高1.5米
【核心能力】木甲防御：木质甲片可硬化，抵挡低阶刀剑劈砍；同时能从地面吸收周围树木的生命力恢复伤势。
【弱点】火属性攻击能点燃其木质甲片，造成持续灼烧伤害。', '[{"item_id": "mh-h1-7", "name": "一阶木属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-265", "name": "木甲片（适合制作低级盾牌或铠甲衬片）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-018', '水泡鱼', '魔兽', 6, 4, 7, 5, '水', '【外观】体呈球形，通体透明带淡蓝色，内部可见器官，嘴部细小，鳍如薄纱，游动时身体像水泡一样晃动。
【体型】直径0.3米
【核心能力】水泡困敌：从口中吐出黏性水泡，包裹猎物头部使其窒息，水泡可保持五息不破裂。
