INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-019', '熔岩虫', '魔兽', 6, 4, 7, 5, '火', '【外观】身体呈蠕虫状，体表为暗红色且带有熔岩般的光泽，头部有六只细小触角，身体蠕动时留下焦痕。
