INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-020', '雪狐', '魔兽', 6, 4, 7, 5, '冰', '【外观】全身雪白绒毛，耳朵尖长呈淡蓝色，尾巴蓬松且有冰晶状末端，眼睛为浅蓝色，脚掌宽厚。
