INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-021', '巨石傀儡', '魔兽', 6, 4, 7, 5, '土', '【外观】由不规则的岩石拼凑而成的人形，身体粗犷，头部有两块发光的黄色晶石作为眼睛，手臂粗壮。
