INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-022', '旋风鬣犬', '魔兽', 6, 4, 7, 5, '风', '【外观】体型像大型犬，毛发呈灰白色，脖颈周围有一圈倒立的鬃毛，奔跑时鬃毛会形成小型漩涡。
