INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-023', '雷光蝗', '魔兽', 6, 4, 7, 5, '雷', '【外观】身体呈黄绿色，翅膀透明带蓝色电光纹路，后腿强壮，复眼大而突出，触角细长如天线。
