INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-024', '暗影猫', '魔兽', 6, 4, 7, 5, '暗', '【外观】体毛漆黑如墨，眼睛在暗处呈幽绿色，尾巴细长且末端有暗紫色光点，体型纤细灵巧。
