INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-025', '剧毒蝎', '魔兽', 6, 4, 7, 5, '毒', '【外观】外壳呈暗红色，背甲有倒刺，尾钩粗大呈深紫色，螯钳巨大且表面有绿色毒斑，复眼密集。
