INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-026', '藤蔓蛇', '魔兽', 6, 4, 7, 5, '木', '【外观】身体细长如藤蔓，体色为深绿色带有棕色斑点，盘绕在树枝上难以分辨，头部细小平滑。
