INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-027', '炎尾蜥', '魔兽', 6, 4, 7, 5, '火', '【外观】全身覆盖暗红色鳞片，尾部末端燃着一簇橙黄色火焰，瞳孔呈竖线状，口中有细密尖牙。
