INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-028', '霜纹蛙', '魔兽', 6, 4, 7, 5, '冰', '【外观】皮肤呈淡蓝色，背部有白色霜状纹路，鼓起的双眼为冰蓝色，腹部柔软且半透明，隐约可见内脏。
