INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-029', '青翼蝠', '魔兽', 6, 4, 7, 5, '风', '【外观】双翼展开呈半透明青色，翼膜薄如蝉翼；身躯细小如成人拳头，覆盖灰色短毛；耳朵尖长，嘴部细窄，可发出高频声波。
