INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-030', '岩壳龟', '魔兽', 6, 4, 7, 5, '土', '【外观】背壳由灰褐色不规则岩石拼接而成，表面布满青苔和细小裂纹；四肢粗短覆有厚皮，头部扁平，眼珠呈土黄色，行动缓慢。
