INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-031', '电纹蛛', '魔兽', 6, 4, 7, 5, '雷', '【外观】身体漆黑，八条细长步足上带有黄色电纹，腹部呈椭圆形，背上有闪电状斑纹；八只复眼闪烁微弱的电弧，吐丝器末端可见细小电火花。
