INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-032', '暗影鼠', '魔兽', 6, 4, 7, 5, '暗', '【外观】皮毛漆黑如炭，没有光泽，在阴暗处近乎隐形；体型如普通野猫，细长尾无毛，眼睛为暗红色，喜欢缩在阴影中。
