INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-033', '毒囊蜂', '魔兽', 6, 4, 7, 5, '毒', '【外观】体型如成人拇指，黄黑相间的环纹比普通马蜂更鲜艳，尾部毒针粗长呈墨绿色，腹部胀大如囊肿，飞行时发出低沉的嗡嗡声。
