INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-034', '青木蛇', '魔兽', 6, 4, 7, 5, '木', '【外观】通体翠绿色，鳞片细腻光滑，腹部有浅黄色横纹；头部扁平呈三角形，眼瞳为深绿色，舌信分叉，常缠绕在树枝上伪装成藤蔓。
【体型】体长1.5米，粗如成人拇指
【核心能力】藤蔓缠绕：催动周围的细藤或树枝快速生长，缠住猎物的四肢或武器；木愈再生：受到非致命伤时，伤口处会缓慢长出木质纤维止血，恢复速度是普通蛇类的两倍。
【弱点】火属性攻击可烧毁其催生的藤蔓并造成有效伤害；冰属性攻击可降低其再生速度。', '[{"item_id": "mh-h1-7", "name": "一阶木属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-575", "name": "青木蛇鳞（磨粉后与草药混合可促进皮肉伤愈合）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-574", "name": "青木蛇毒（微量麻痹毒液，可麻痹小型猎物）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-035', '流沙蝎', '魔兽', 6, 4, 7, 5, '土', '【外观】全身覆盖土黄色甲壳，带有不规则沙粒纹理；双螯粗壮不对称，右螯稍大；尾部弯翘，毒针末端呈暗灰色，能在沙中快速潜行留下波纹。
【体型】体长0.6米（含尾），螯展0.3米
【核心能力】流沙陷阱：快速挖沙制造一个直径2米的流沙区域，让目标下陷；沙隐突袭：钻入沙下移动并突然从目标脚下钻出攻击。
【弱点】水属性攻击可使沙地黏结，阻碍其潜行；跳离地面后其行动会变得笨拙。', '[{"item_id": "mh-h1-6", "name": "一阶土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-348", "name": "流沙蝎的双螯（可打造低阶钩爪工具）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-484", "name": "蝎尾毒针（内含神经毒素，可制作麻痹飞镖）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-036', '霜甲虫', '魔兽', 6, 4, 7, 5, '冰', '【外观】甲壳呈半透明的冰蓝色，表面覆盖一层薄霜，六足粗短覆有细密刚毛，口器为咀嚼式，头顶有一根极短的触角，周身散发出白蒙蒙的寒气。
【体型】体长0.2米，壳高0.1米
【核心能力】冰甲硬化：将冰属性能量注入甲壳，使外壳硬度提升，可抵御普通刀剑斩击；寒气喷吐：从口器喷出零下温度的寒气，在2米范围内形成冰雾，降低敌人速度。
【弱点】火属性攻击可融化冰甲并对其造成额外灼伤；腹部关节处防御薄弱，易被穿刺。', '[{"item_id": "mh-h1-5", "name": "一阶冰属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-565", "name": "霜甲虫的外壳（可打磨成冰属性护甲片）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-189", "name": "寒霜腺液（低温液体，可作短效冷却剂）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-037', '风刃隼', '魔兽', 6, 4, 7, 5, '风', '【外观】羽毛呈青灰色，翼尖锋利如刀刃，尾羽修长分叉；喙部尖锐呈钩状，鹰眼锐利，飞行时速极快，常在空中盘旋俯冲。
【体型】体长0.4米，翼展1.2米
【核心能力】风翼斩：俯冲时双翼边缘凝聚青色风刃，切割目标造成深度割伤；气流操控：快速扇翅制造小范围旋风，干扰敌人视线和平衡。
【弱点】地面陷阱或网兜可限制其飞行优势；雷属性攻击可借气流传导，使其麻痹。', '[{"item_id": "mh-h1-3", "name": "一阶风属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-589", "name": "风刃隼的翼羽（可制作轻便箭矢尾羽或风系符纸笔）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-518", "name": "隼喙（坚硬锋利，可作雕刻工具）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-038', '火绒兔', '魔兽', 6, 4, 7, 5, '火', '【外观】外形似普通野兔，但全身绒毛呈火红色，背脊有一道橙黄色火焰纹路；耳朵长而竖起，末端微微发红，眼睛为琥珀色，尾巴短小如绒球。
【体型】体长0.3米，肩高0.2米
【核心能力】火绒弹射：用力蹬地时，脚下会爆出一小团火焰，产生短距离弹跳加速，逃跑速度极快；毛发热能储存：长期吸收地热后，绒毛可短暂发热，触碰者会感到灼烫。
【弱点】水属性攻击可打湿其绒毛，使火属性能量无法储存；极其怕冷，低温环境会萎靡。', '[{"item_id": "mh-h1-1", "name": "一阶火属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-362", "name": "火绒兔毛（蓬松保暖，摩擦可生微火，适合做火绒）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-122", "name": "兔爪骨（磨碎后可作低级助燃粉末）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-039', '黑水蛭', '魔兽', 6, 4, 7, 5, '暗', '【外观】通体漆黑如墨，体表光滑无鳞，呈圆柱形；头部有一个圆形吸盘，边缘密布细齿，身体可伸缩至原有长度的两倍，游动时无声无息。
【体型】体长0.1米（伸展时可达0.2米）
【核心能力】暗能吸血：用吸盘吸附后，可释放暗属性能量麻痹伤口，同时吸食目标斗气或血液，造成虚弱感；暗影潜游：在水中几乎不可见，仅靠水面微弱的阴影波动感知其存在。
【弱点】光属性攻击可使其暴露并灼伤皮肤；脱离水环境后行动极其迟缓，易被捕杀。', '[{"item_id": "mh-h1-9", "name": "一阶暗属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-635", "name": "黑水蛭的吸盘（干燥后可作止血吸附器）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-218", "name": "暗凝血液（粘稠液体，加入低级暗系斗技可提升隐蔽性）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-040', '翠羽鸮', '魔兽', 6, 4, 7, 5, '木', '【外观】羽毛以翠绿色为主，腹部有浅黄色绒毛，翅膀内侧有木质纹理；头部圆大，面部呈心形，眼睛大而圆呈淡金色，喙短而钩，爪呈树皮色。
【体型】体长0.3米，翼展0.7米
【核心能力】木化伪装：静止时羽毛可模拟树叶和树皮纹理，与周围树木融为一体，极难发现；种子投掷：从嗉囊中吐出铁木种子，撞击目标后快速发芽缠绕，限制行动。
