INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-041', '雷纹角牛', '魔兽', 6, 4, 7, 5, '雷', '【外观】体型壮硕如普通野牛，皮毛呈深灰色，背脊和四肢有蓝色闪电状纹路；头顶一对粗壮弯角，角尖缠绕细弱电弧，走动时四肢踏地会留下微小的电火花。
【体型】体长2.5米，肩高1.5米，体重约500公斤
【核心能力】雷电冲撞：低头冲刺时，双角汇聚雷属性能量，在撞击瞬间释放电流，造成麻痹和钝伤；踏地电击：用力跺脚时，以自身为中心3米范围内的地面会释放一圈低压电流，击退小体型敌人。
