INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-042', '毒棘豪猪', '魔兽', 6, 4, 7, 5, '毒', '【外观】体型如中型犬，全身覆盖黑白相间的硬棘，尖端呈紫色；背部棘刺比普通豪猪更粗长且中空，内含毒液，鼻子短小，眼睛小而凶光毕露。
