INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-043', '冰晶蟹', '魔兽', 6, 4, 7, 5, '冰', '【外观】甲壳呈半透明的冰蓝色，表面有六角形冰晶图案；一对螯足粗大，螯钳内侧有锯齿状冰刺；步足修长，关节处凝结着细小的冰霜，行走时留下冰痕。
