INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-044', '沙隐蚺', '魔兽', 6, 4, 7, 5, '土', '【外观】通体土黄色，鳞片细密如沙粒，背部有深褐色菱形斑纹；头部扁平，眼睛退化，靠感知地面震动捕猎，身体粗壮，可无声地在沙中穿行。
