INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-045', '电光蝗', '魔兽', 6, 4, 7, 5, '雷', '【外观】体型如成人手指，全身覆盖淡黄色甲壳，背部长有细小的蓝色电纹；后腿强壮，弹跳力惊人，翅膀透明且扇动时会发出噼啪的微弱电响声。
