INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-046', '暗语猿', '魔兽', 6, 4, 7, 5, '暗', '【外观】全身覆盖深灰色粗毛，面部皮肤呈灰白色，眼睛为全黑色，没有眼白；手臂粗长过膝，指爪尖锐，能直立行走，但常四肢并用攀爬，口中发出低沉的咕噜声。
