INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-047', '腐根藤', '魔兽', 6, 4, 7, 5, '木', '【外观】形似枯死的藤蔓，呈深褐色，表面有黑色斑点，藤条上稀疏分布着暗绿色的细叶；主藤粗如成人手腕，分支众多，平时瘫软在地面上看似一截死藤。
