【核心能力】根须缠绕：从地下伸出无数细小的白色根须，缠绕踩踏者的脚踝并将其拖倒；腐木尖刺：分支藤条末端会硬化形成木质尖刺，刺入皮肤后会注入腐烂毒素，导致伤口溃烂。
【弱点】火属性攻击可快速焚烧其藤蔓主体；切断其与地下根系的连接可使其失去行动力。', '[{"item_id": "mh-h1-7", "name": "一阶木属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-438", "name": "腐根藤的韧皮（干燥后可搓成坚韧绳索，有轻微防水性）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-437", "name": "腐木毒素（从尖刺中提取，可制低级腐烂毒药）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-048', '火羽雀', '魔兽', 6, 4, 7, 5, '火', '【外观】体型娇小如麻雀，全身羽毛呈橙红色，尾羽末端燃着微小火焰；喙短小而坚硬，眼睛明亮如赤珠，飞行时身后会拖出一道细细的火线。
【体型】体长0.1米，翼展0.2米
【核心能力】火花溅射：啄击或受惊时，羽毛会抖落许多细小的火星，落在干燥物上会引起小火；炎羽护体：情绪激动时，周身羽毛会微微发红发热，触碰有灼手感。
【弱点】水属性攻击可打湿羽毛使其暂时失去火焰特性；耐力差，持续战斗后会因能量耗尽而萎靡。', '[{"item_id": "mh-h1-1", "name": "一阶火属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-363", "name": "火羽雀的羽毛（可拼接成低阶生火扇）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-520", "name": "雀粪（晒干后可作低阶炼药燃料，燃烧持久无烟）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-049', '毒纹蛙', '魔兽', 6, 4, 7, 5, '毒', '【外观】皮肤呈鲜艳的紫绿色，背部有黑色环状毒纹，鼓起的双眼周围有黄色圈；体表分泌一层粘稠毒液，在阳光下微微发光，体型比普通青蛙大一倍。
【体型】身长0.15米，蹲坐高0.08米
【核心能力】毒液喷射：从皮肤腺体喷射出细线状毒液，射程3米，接触皮肤会产生灼烧感和水泡；毒肤接触：触碰其皮肤会被毒液沾染，若皮肤有伤口则毒液入体，引起头晕和麻痹。
【弱点】火属性攻击可烧干其体表毒液，使其失去毒性；干燥环境会使其皮肤干裂，毒液分泌减少。', '[{"item_id": "mh-h1-10", "name": "一阶毒属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-290", "name": "毒纹蛙的皮肤（风干后磨粉，可制低阶毒药或驱虫药）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-298", "name": "毒腺液（浓稠毒液，涂抹暗器可产生腐蚀效果）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-050', '风影猫', '魔兽', 6, 4, 7, 5, '风', '【外观】体型修长如普通家猫，皮毛呈银灰色，背脊有一条青色毛流，奔跑时会随风飘动；耳朵尖长且灵敏，尾巴蓬松修长，眼睛为浅青色，瞳孔随光线变化。
【体型】体长0.5米（不含尾），肩高0.25米
【核心能力】风步加速：奔跑时在脚下凝聚风属性能量，使自身速度大幅提升，短距离冲刺可达普通猎豹的速度；微风爪击：爪尖凝聚风刃，划过目标后留下浅而长的切口。
【弱点】地面障碍物或狭窄空间会限制其加速能力；雷属性攻击可借风传导使其麻痹。', '[{"item_id": "mh-h1-3", "name": "一阶风属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-594", "name": "风影猫的毛（可编织成轻便的围巾或护腕，轻微增加行动速度）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-409", "name": "猫爪尖刺（磨制后可作快速切割工具）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-051', '冰牙狼', '魔兽', 6, 4, 7, 5, '冰', '【外观】体型如普通灰狼，但皮毛呈灰白色，颈部有一圈较长的白色鬃毛；牙齿呈半透明的冰蓝色，口中呼出白雾，眼睛为浅蓝色，夜间会发出微弱的寒光。
【体型】体长1.5米（不含尾），肩高0.7米，体重约40公斤
【核心能力】冰牙撕咬：用冰蓝色的牙齿撕咬时，会在伤口处留下冰晶，造成冻结和撕裂双重伤害；寒冰嚎叫：仰天长嚎时，从口中喷出直径3米的冰雾，降低范围内目标的体温和速度。
【弱点】火属性攻击可融化其冰牙并削弱其嚎叫效果；落单时战斗力下降。', '[{"item_id": "mh-h1-5", "name": "一阶冰属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-146", "name": "冰牙狼的狼牙（可制冰系匕首或箭头）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-408", "name": "狼皮（保暖且防水，可制防寒斗篷）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-052', '土甲龙', '魔兽', 6, 4, 7, 5, '土', '【外观】体型如小型犀牛，全身覆盖厚重的深棕色板甲，甲片边缘有钝刺；头部短宽，鼻端有一根短钝的角，四肢粗壮如柱，尾巴短而粗重，行动沉稳有力。
【体型】体长3米，肩高1.8米，体重约1吨
【核心能力】地动冲击：用头角撞击地面，引发小范围地震波，使5米内的敌人失去平衡；石甲防御：将土属性能量注入甲片，使身体防御力提升至可抵挡普通刀剑斩击的程度。
【弱点】腹部无甲片保护，是薄弱点；雷属性攻击可震裂甲片缝隙；行动缓慢，敏捷型对手可绕后攻击。', '[{"item_id": "mh-h1-6", "name": "一阶土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-173", "name": "土甲龙的板甲碎片（可制重盾或铠甲补片）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-508", "name": "钝角粉末（磨碎后加入土系斗技可增加威力）。", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-053', '熔岩啮龟', '魔兽', 6, 4, 7, 5, '火', '【外观】龟壳布满焦黑裂纹，缝隙中渗出暗红岩浆，四肢短粗覆有鳞片，眼珠赤红如炭。
【体型】壳长0.8米，肩高0.3米，体重约40公斤
【核心能力】口中喷溅滚烫岩浆弹，射程5米，溅射范围1米；遇袭时缩入壳内，壳表温度升至200度。
【弱点】腹部甲板薄脆，低温水属性攻击可使其壳裂；行动迟缓，游走战法有效。', '[{"item_id": "mh-h1-1", "name": "一阶火属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-394", "name": "熔岩龟壳碎片（铸器材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-371", "name": "炙热龟肉（可食，微带火辣）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-054', '霜纹水蟒', '魔兽', 6, 4, 7, 5, '水', '【外观】通体银白鳞片泛蓝光，背部有三条冰蓝波纹，头颅呈三角，瞳孔如冰晶般透亮。
【体型】体长2.5-3米，腰围约0.2米，体重30公斤
【核心能力】口中喷出高压冰水柱，射程8米，冲击力可击碎一阶斗气护体；尾击附带冰冻效果，接触部位结冰迟缓。
【弱点】蛇类通病七寸处防御薄弱；干燥高温环境会降低其冰水威力；腹部鳞片硬度不如背部。', '[{"item_id": "mh-h1-2", "name": "一阶水属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-333", "name": "水蟒鳞片（制甲材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-150", "name": "冰腺（可提取冰属性淬毒剂）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-055', '风刃灵蝠', '魔兽', 6, 4, 7, 5, '风', '【外观】双翼展开薄如蝉翼，边缘泛青白锋锐光芒，体表覆盖短绒灰毛，耳廓大而圆，面部酷似鼠类。
【体型】体长0.2米，翼展0.8米，体重仅1公斤
【核心能力】振翅时释放三道半透明风刃，最远可切割15米外的目标；利用超声波定位，黑暗环境闪避率极高。
【弱点】惧怕强光和火焰，被火光照耀时行动混乱；风刃威力随距离递减，近身后脆弱不堪。', '[{"item_id": "mh-h1-3", "name": "一阶风属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-612", "name": "风翼膜（缝制披风材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-490", "name": "蝠粪（药肥，可促生风属性药材）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-056', '岩甲地蝎', '魔兽', 6, 4, 7, 5, '土', '【外观】体表覆盖灰褐色岩石状甲壳，六足粗壮带倒刺，尾部蝎针呈钝锥状，泛暗沉土黄光泽。
【体型】体长1.2米（含尾），肩高0.5米，体重80公斤
【核心能力】钻地突袭——能在2秒内钻入地下，再从目标脚下破土而出；蝎针刺入后释放土毒，使伤口石化僵硬。
【弱点】腹部甲壳接缝处薄弱，雷属性攻击可透过甲壳传递震伤内脏；钻地时无法感知地面震动，可预先避开。', '[{"item_id": "mh-h1-6", "name": "一阶土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-204", "name": "岩蝎甲壳（盾牌材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-171", "name": "土毒腺（炼毒原料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-057', '雷纹跳蛛', '魔兽', 6, 4, 7, 5, '雷', '【外观】八足细长覆有蓝紫色雷纹，腹部圆鼓呈银灰，眼列八只闪烁电弧跃动，绒毛带电竖立。
【体型】体长0.15米，足展0.3米，体重0.5公斤
【核心能力】跳跃时腿间释放电弧，可跳跃10米距离并麻痹接触目标；吐丝带静电，黏附时传导微弱电流持续麻痹。
【弱点】水浸会使雷电短路，放电后需短暂充能；体型微小，被重击或踩踏易毙命；怕强风干扰跳跃轨迹。', '[{"item_id": "mh-h1-4", "name": "一阶雷属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-554", "name": "雷蛛丝（导电丝线，可用于低级阵法布线）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-582", "name": "静电绒毛（摩擦生电材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-058', '冰晶雪蛤', '魔兽', 6, 4, 7, 5, '冰', '【外观】体表半透明冰蓝，皮肤光滑如冻瓷，背部散落六角冰晶凸起，眼睛呈纯白无瞳，口裂宽大。
【体型】体长0.3米，宽0.2米，体重约5公斤
【核心能力】从背部冰晶喷出冰雾，制造3米范围低温区域，使目标移速下降；舌头弹出分泌冰毒，可在接触点冻结毛细血管。
【弱点】高温环境会使其冰晶融化，冰雾浓度降低；腹部皮肤极薄，钝器击打即可重伤。', '[{"item_id": "mh-h1-5", "name": "一阶冰属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-155", "name": "冰蛤舌（可入药，治热毒攻心）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-132", "name": "冰晶粉（炼制冷冻弹药材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-059', '暗影潜鼠', '魔兽', 6, 4, 7, 5, '暗', '【外观】皮毛漆黑如墨，无反射光泽，在暗处近乎隐形；双眼细小呈暗红，耳廓退化，门齿外露尖锐。
【体型】体长0.4米（含尾），肩高0.15米，体重3公斤
【核心能力】释放10米范围的暗影气场，降低范围内照明亮度，干扰人类视线和斗气感知；咬合带暗毒，伤口持续溃烂且难愈合。
【弱点】强光照射会瞬间破除暗影气场，使其暴露；火属性攻击可灼烧暗毒；嗅觉虽好但易被刺激性气味扰乱。', '[{"item_id": "mh-h1-9", "name": "一阶暗属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-249", "name": "暗鼠皮毛（夜行衣材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-237", "name": "暗毒牙（可淬毒）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-060', '毒蘑菇精', '魔兽', 6, 4, 7, 5, '毒', '【外观】形如巨型蘑菇，伞盖呈紫绿色布满脓疱，菌柄粗壮长有细密吸盘，有两条短小的触须状伪足移动。
【体型】伞盖直径0.5米，菌柄高0.6米，体重15公斤
【核心能力】喷发孢子云——每秒释放数千细小微粒，吸入后产生眩晕、幻觉，持续失去平衡感；伞盖脓疱破裂会溅射腐蚀液。
【弱点】火属性可瞬时烧尽孢子云；风吹可驱散孢子；菌柄脆弱，斩断即死；怕干燥环境。', '[{"item_id": "mh-h1-10", "name": "一阶毒属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-303", "name": "毒菇孢子粉（投毒材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-448", "name": "菌柄汁液（可调制麻痹药剂）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-061', '木甲螳螂', '魔兽', 6, 4, 7, 5, '木', '【外观】体色翠绿带木质纹理，前肢如镰刀状且边缘呈锯齿，复眼由数百小眼组成，翅鞘半透明如嫩叶。
【体型】体长0.3米，前肢展开0.4米，体重2公斤
【核心能力】利用木属性伪装融入树丛，静止时与树枝无异，发动偷袭时速度极快；前肢锯切附带木毒，可令伤口木质化僵硬。
【弱点】火属性攻击能烧毁其伪装外壳，暴露行踪；水性潮湿环境会使其木质甲壳变软；复眼对快速移动物体敏感，静止不动时反而难被发现。', '[{"item_id": "mh-h1-7", "name": "一阶木属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-493", "name": "螳螂镰刃（可制匕首或锯条）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-271", "name": "木质翅鞘（轻甲材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-062', '烬火烈狐', '魔兽', 6, 4, 7, 5, '火', '【外观】皮毛赤红如烧炭，尾部末端有一簇不熄小火苗，耳尖竖立有黑毛，瞳色金黄如熔金。
【体型】体长0.6米（含尾），肩高0.3米，体重8公斤
【核心能力】甩尾时释放火星弧线，落地后形成持续5秒的燃烧带；口中喷吐热浪，使5米内空气升温至80度，令人呼吸不畅。
【弱点】水属性攻击可浇灭尾部火苗，使其暂时失去燃烧能力；嗅觉灵敏但易被浓烟干扰。', '[{"item_id": "mh-h1-1", "name": "一阶火属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-403", "name": "狐尾火绒（引火材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-361", "name": "火狐毛皮（保暖制衣材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-063', '水纹蜃蛤', '魔兽', 6, 4, 7, 5, '水', '【外观】贝壳呈乳白泛水波纹，壳缘柔软，肉足宽大能吸附岩壁，从壳缝伸出两根透明触须感知水流。
【体型】壳长0.2米，宽0.15米，体重2公斤
【核心能力】释放水汽幻象——喷出折射水雾，制造一个直径3米的虚假影像，可模拟巨石或树桩遮挡自身；水流感知半径20米，能提前察觉靠近者。
【弱点】一旦闭合贝壳，水雾即散，幻象消失；雷属性攻击可穿透水雾直接伤害本体；离开水后行动缓慢。', '[{"item_id": "mh-h1-2", "name": "一阶水属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-479", "name": "蜃蛤珍珠（可入药安神）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-502", "name": "贝壳碎片（可磨粉作水属性符墨）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-064', '卷风雀', '魔兽', 6, 4, 7, 5, '风', '【外观】体型纤细，羽毛青灰色边缘带白，双翅狭长如镰刀，尾部有两根极长的飘羽，喙短小尖锐。
【体型】体长0.2米，翼展0.5米，体重0.3公斤
【核心能力】疾速盘旋时卷起小型旋风，直径1米，可扰乱投掷物飞行轨迹或扬起沙尘遮蔽视线；飞行时速可达80公里，极擅长闪避。
【弱点】耐力差，高速飞行不超过5分钟即需休息；地面战斗力为零；怕网兜和密集投掷。', '[{"item_id": "mh-h1-3", "name": "一阶风属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-164", "name": "卷风尾羽（可制箭羽，增加飞行稳定性）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-521", "name": "雀鸣骨（可制哨子）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-065', '碎石蛮牛', '魔兽', 6, 4, 7, 5, '土', '【外观】体型敦实，皮毛粗糙如砂岩，双角粗短呈锥状且表面有岩纹，四肢粗壮蹄如铁锤，鼻息喷出灰色石粉。
【体型】体长2米，肩高1.2米，体重500公斤
【核心能力】冲锋时将土属性斗气注入地面，前方5米土地剧烈翻涌，形成碎石浪，令目标站立不稳；头部撞击可崩裂普通岩石，威力堪比一阶土系斗技。
【弱点】关节笨拙，转向慢；冰属性攻击可冻住其蹄部与地面接触，使其失去冲锋借力；怕敏捷型对手绕后。', '[{"item_id": "mh-h1-6", "name": "一阶土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-475", "name": "蛮牛皮（制甲材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-399", "name": "牛角粉（可加固建筑粘合剂）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-066', '静电飞蛾', '魔兽', 6, 4, 7, 5, '雷', '【外观】翅膀宽大覆盖银灰磷粉，边缘有锯齿状紫光纹路，触角如细丝末端分叉，腹部分节泛淡蓝荧光。
【体型】翼展0.3米，体长0.1米，体重0.1公斤
【核心能力】飞行时翅膀摩擦释放静电，触碰时产生麻痹电击（强度相当于一阶雷系斗技）；磷粉散落空气中，遇摩擦即爆出火花，形成直径2米的电火花区。
【弱点】翅膀一旦沾水即失去摩擦起电能力，无法放电；怕强风吹散磷粉；寿命短，仅存活半个月。', '[{"item_id": "mh-h1-4", "name": "一阶雷属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-580", "name": "静电磷粉（可辅助低级雷系阵法充能）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-476", "name": "蛾翅薄膜（绝缘材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-067', '寒髓冰蛇', '魔兽', 6, 4, 7, 5, '冰', '【外观】鳞片细密如冰晶叠层，通体银白近乎透明，腹侧有淡蓝光带，头扁平呈梭形，瞳孔竖直如针。
【体型】体长1.5-2米，直径0.06米，体重5公斤
【核心能力】身体可蜷曲成环，瞬间释放半径2米的寒气爆发，冻结范围内水分，使地面变滑或封冻武器；毒牙注入冰毒液，使伤口组织局部冻结坏死。
【弱点】温血生物靠近时会因体温感应被蛇察觉，可用火属性预热斗气反制；蛇身虽硬但脆，重击可断。', '[{"item_id": "mh-h1-5", "name": "一阶冰属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-153", "name": "冰蛇鳞片（可制冰属性暗器）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-185", "name": "寒毒液（炼毒材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-068', '夜影猎蝠', '魔兽', 6, 4, 7, 5, '暗', '【外观】皮膜漆黑无光，翼骨末端有利爪，头部有两根短角，嘴部露出四颗尖牙，眼窝深陷只有两点幽红光芒。
【体型】体长0.3米，翼展1米，体重2公斤
【核心能力】发射暗影音波——以声波探测的同时，利用暗属性斗气在30米范围内制造低频噪音，干扰人类感知平衡；俯冲攻击时爪部缠绕暗影，可短暂遮蔽目标的视觉。
【弱点】光明类斗技可直接破除其暗影遮蔽效果；怕强声干扰自身音波定位（如铜锣声）；翼膜脆弱，箭矢可穿透。', '[{"item_id": "mh-h1-9", "name": "一阶暗属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-178", "name": "夜影翼膜（制夜行披风材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-489", "name": "蝙牙（可制低级暗器箭头）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-069', '毒棘豪猪', '魔兽', 6, 4, 7, 5, '毒', '【外观】体表覆盖黑白相间棘刺，每根棘刺尖端呈紫红色，背部脊线隆起，吻部尖长，眼小如豆。
【体型】体长0.7米，肩高0.3米，体重12公斤
【核心能力】弹射棘刺——受惊时背部肌肉收缩，可一次性射出10-15根棘刺，射程8米，刺尖带毒使伤口肿痛麻痹；棘刺可缓慢再生，每日恢复3-5根。
【弱点】腹部无刺，滚翻后仰便可暴露弱点；火属性可烧毁棘刺使其失去远程武器；怕速度型对手。', '[{"item_id": "mh-h1-10", "name": "一阶毒属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-283", "name": "毒棘刺（可制毒箭）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-501", "name": "豪猪皮（可制防刺手套）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-070', '青藤猿', '魔兽', 6, 4, 7, 5, '木', '【外观】毛发深绿如青苔，四肢修长手指具吸盘，尾巴卷曲有力可抓握树枝，面部裸露皮肤呈淡褐色，瞳孔竖椭圆。
【体型】体长1米（含尾），肩高0.5米，体重20公斤
【核心能力】操控周围藤蔓缠绕敌人10秒，藤蔓坚韧需一阶斗气才能扯断；从掌心释放木属性种子，触地即长出尖刺藤条，形成1米范围的荆棘陷阱。
【弱点】火属性可快速烧毁藤蔓和荆棘；冰属性可冻结藤蔓使其变脆断裂；智商虽高但易被挑衅激怒，失去冷静。', '[{"item_id": "mh-h1-7", "name": "一阶木属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-449", "name": "藤猿毛（可织韧性绳索）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-214", "name": "掌心种子（可种出低级荆棘藤）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-071', '熔岩蜥蜴', '魔兽', 6, 4, 7, 5, '火', '【外观】皮肤赤红带黑色斑点，背脊有锯齿状的橙色鳍状物，尾巴粗壮末端呈锤状，舌头分叉且泛赤红。
【体型】体长0.8米（含尾），肩高0.2米，体重6公斤
【核心能力】尾部锤击地面时释放小范围火浪，半径2米内地面灼烧，持续5秒；口中蓄热后可喷出高热度气流，射程5米，能点燃干燥物。
【弱点】腹部鳞片较薄，被掀翻后即为破绽；水性潮湿环境可抑制其火属性输出，使其喷吐威力减半。', '[{"item_id": "mh-h1-1", "name": "一阶火属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-481", "name": "蜥蜴皮（制耐火手套材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-382", "name": "熔岩尾锤（可打造锤头）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-072', '水泡鱼', '魔兽', 6, 4, 7, 5, '水', '【外观】体呈球状半透明，皮肤薄如凝胶，能看见内脏隐约阴影，口小如吸管，眼大而无神，腹鳍退化呈须状。
【体型】体长0.15米，直径0.12米，体重0.5公斤
【核心能力】吸入大量水分后膨胀至3倍，然后从口喷射高压水箭，射程10米，水箭有冲击力可击退小型目标；皮肤遇威胁可分泌润滑黏液，脱手率高。
【弱点】离水后身体萎缩失去战斗力，水箭需吸水准备2秒；雷属性攻击在水中有传导加成；体表脆弱，利刃可刺破。', '[{"item_id": "mh-h1-2", "name": "一阶水属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-320", "name": "水泡鱼皮（可制防水袋）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-350", "name": "润滑黏液（可制脱手剂）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-073', '风翎隼', '魔兽', 6, 4, 7, 5, '风', '【外观】羽毛雪白带淡青光泽，双翅边缘锋利如刃，头部有翎羽冠，喙弯钩状，爪黑亮如铁。
【体型】体长0.5米，翼展1.2米，体重5公斤
【核心能力】俯冲时双翅裹挟风刃，可切割木质盾牌和低级皮甲；飞行高度可达200米，视野覆盖半径500米，极难被偷袭。
【弱点】地面搏斗能力弱，一旦落地或被困即无优势；雷击会使羽毛导电，短暂麻痹；巢穴固定，可设伏捕杀。', '[{"item_id": "mh-h1-3", "name": "一阶风属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-605", "name": "风翎羽（可制箭羽和扇子）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-519", "name": "隼爪（可制钩爪武器）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-074', '石甲鼹鼠', '魔兽', 6, 4, 7, 5, '土', '【外观】全身覆盖灰褐色石质甲片，四肢短粗带利爪，头部扁平，眼小退化，鼻端有角质突，状如钻头。
【体型】体长0.5米，肩高0.2米，体重15公斤
【核心能力】钻地时头部角质突高速旋转，可粉碎普通岩石，挖掘速度每小时5米；从口中喷出砂石弹，射程6米，命中造成钝击伤害。
【弱点】怕水——土质甲壳遇水软化；听觉极好但视力为零，可用震地制造干扰；钻地后尾部和后腿露出，可被抓住拖出。', '[{"item_id": "mh-h1-6", "name": "一阶土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-423", "name": "石甲片（制铠材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-639", "name": "鼹鼠爪（可制凿子或挖掘工具）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-075', '雷击蜓', '魔兽', 6, 4, 7, 5, '雷', '【外观】体纤细，四翅透明带紫电纹路，复眼呈紫金色，腹部细长节状，尾部有一小撮荧光蓝。
【体型】体长0.08米，翼展0.12米，体重0.01公斤
【核心能力】飞行时尾部释放静电弧线，触碰后产生轻微电击，可麻痹小型动物；翅膀高速振翅时可释放高频嗡鸣，干扰半径5米内的听觉和感知。
【弱点】翅膀沾水即无法飞行，更无法放电；体型过小，一巴掌可拍死；怕火和烟；寿命短，仅数天。', '[{"item_id": "mh-h1-4", "name": "一阶雷属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-532", "name": "雷击蜓翅膀（可制微型发电机材料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-195", "name": "尾部荧光液（可制夜光涂料）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-076', '霜角鹿', '魔兽', 6, 4, 7, 5, '冰', '【外观】皮毛厚实银白，颈部有长鬃，公鹿头顶双角晶莹如冰雕，角尖散发寒气，蹄子宽大适合雪地行走，鼻孔呼出白雾。
【体型】体长1.5米，肩高1米，体重150公斤
【核心能力】低头撞击时双角释放冰属性斗气，触碰点会瞬间结冰，使目标部位冻伤；蹄踏地面可制造半径1米薄冰区，降低追捕者速度。
【弱点】夏季高温会使角部冰晶融化，冰属性能力减弱；速度虽快但转弯半径大，可设伏或包围；角部虽硬但颈部脆弱。', '[{"item_id": "mh-h1-5", "name": "一阶冰属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-571", "name": "霜角（可制冰系法器）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-629", "name": "鹿皮（制保暖衣物）", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-077', '暗影潜伏蛛', '魔兽', 6, 4, 7, 5, '暗', '【外观】通体漆黑如焦油，八足细长覆盖倒刺，腹部有暗灰斑纹，眼列八只呈暗红，步足末端有绒毛可吸附岩壁。
【体型】体长0.3米，足展0.6米，体重2公斤
【核心能力】在绝对黑暗中释放暗影网，蛛网附有暗属性遮蔽效果，即使持有光源也仅能看清3米范围；咬合时注入暗毒，使中毒者逐渐失去视觉，视野随毒素扩散而缩小。
