INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-078', '毒瘴蛙', '魔兽', 6, 4, 7, 5, '毒', '【外观】皮肤粗糙满是疙瘩，体色土黄带暗绿斑纹，疙瘩顶端有孔可分泌毒液，眼大鼓出，瞳孔呈横线。
