INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-113', '风吼狮', '魔兽', 14, 10, 15, 13, '风', '【外观】金色鬃毛环绕脖颈，鬃毛间有青色气流漩涡，四足踏风行走离地半寸，双眼如风眼般旋转。
