INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-114', '冰晶蛇', '魔兽', 14, 10, 15, 13, '冰', '【外观】蛇鳞如剔透冰晶，身体半透明，内部可见冰蓝色血液流动，头顶有菱形冰冠，眼珠如寒冰珠。
