INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-115', '雷角牛', '魔兽', 14, 10, 15, 13, '雷', '【外观】壮硕如野牛，头顶双角弯曲向前，角上缠绕银色电弧，皮毛呈灰蓝色，背上有一排雷纹。
