INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-116', '毒雾蝶', '魔兽', 14, 10, 15, 13, '毒', '【外观】两对翅膀呈暗紫色渐变，翅膀边缘有剧毒鳞粉闪烁荧光，身体细长如针，触须末端带毒囊。
