INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-129', '熔岩蝎', '魔兽', 14, 10, 15, 13, '火', '【外观】通体赤红甲壳，挥舞着四对螯钳，尾针如熔铁般泛着暗红光，背部有龟裂纹熔岩纹路。
