【弱点】火属性斗气能烧毁藤蔓，雷属性可麻痹其神经。', '[{"item_id": "mh-h2-7", "name": "二阶木属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-269", "name": "木藤猴爪", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-367", "name": "灵木果核", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-136', '暗影蝙蝠', '魔兽', 14, 10, 15, 13, '暗', '【外观】通体漆黑如墨，双眼退化呈白色，翼膜边缘有暗紫色纹路，倒挂时融入阴影难以察觉。
