INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-137', '水纹鲛', '魔兽', 14, 10, 15, 13, '水', '【外观】银白色鳞片如水流般柔滑，鱼鳍呈半透明状，口中密布三排锯齿，尾鳍分叉如双刃。
