INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-138', '沙暴蝎', '魔兽', 14, 10, 15, 13, '风/土', '【外观】黄褐色甲壳粗糙如沙砾，螯钳巨大，尾针呈钩状，眼部有透明薄膜护目，能掀起小型沙暴。
