INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-139', '冰霜蝠', '魔兽', 14, 10, 15, 13, '冰', '【外观】白色绒毛覆盖短躯，翼膜晶莹如冰片，嘴部突出的獠牙挂有冰凌，呼出白雾冰晶。
