INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-149', '冰晶蝶', '魔兽', 14, 10, 15, 13, '冰', '【外观】翅膀如六角冰晶拼接而成，透明白色中泛蓝光，身体纤细如冰丝，飞行时飘落雪花。
