INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-152', '水纹龟', '魔兽', 14, 10, 15, 13, '水', '【外观】龟壳呈青蓝色带水波纹，四肢如鳍状，头部圆润，眼珠如黑珍珠，能喷出细水柱。
