INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-168', '毒雾蛤', '魔兽', 14, 10, 15, 13, '毒', '【外观】体表布满暗绿色瘤状疙瘩，不时渗出发光毒液，大嘴宽扁，一双凸眼呈暗黄色，鼓噪时全身膨胀如球
