INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-198', '冰晶蝶', '魔兽', 14, 10, 15, 13, '冰', '【外观】翅膀如冰晶薄片，呈淡蓝色，上有霜花纹理，触角晶莹，身体呈透明状，飞行时留下冰粉轨迹。
