INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-199', '风影鼠', '魔兽', 14, 10, 15, 13, '风', '【外观】毛色灰白，耳朵大如扇，尾部细长，眼睛小而亮，体表有淡淡风纹，奔跑时只留下残影。
