INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-200', '石铠兽', '魔兽', 14, 10, 15, 13, '土', '【外观】形似穿山甲，全身覆盖青灰色鳞甲，背甲层层叠叠，前端有凸起石锥，四爪粗壮，尾巴呈锤状。
