INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-215', '炎火狮鹫', '魔兽', 28, 21, 27, 24, '火/风', '【外观】上半身是金色狮身，下半身为火羽鹰身，翅膀燃烧火焰，头部有赤红鬃毛，喙锋利如刀。
