INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-217', '雷霆巨蝎', '魔兽', 28, 21, 27, 24, '雷/土', '【外观】暗棕色甲壳，背部有蓝色雷电纹路，双钳巨大，尾钩缠绕电弧，眼睛闪烁黄光，行动沉重。
