INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-251', '木岩猿', '魔兽', 28, 21, 27, 24, '木/土', '【外观】体毛棕绿相间，四肢粗壮，手指带木质倒刺，背部有岩石状疣。
