INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-252', '暗影鸦', '魔兽', 20, 15, 19, 18, '暗', '【外观】漆黑羽毛，喙和爪为灰色，双眼血红色，羽毛边缘有暗影流动。
