【弱点】强光可驱散暗影球，灵魂防御斗技可抵抗尖啸。', '[{"item_id": "mh-h3-9", "name": "三阶暗属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-240", "name": "暗羽", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-624", "name": "鸦眼血晶", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-253', '熔岩蝎', '魔兽', 34, 26, 32, 30, '火/土', '【外观】外壳暗红色布满裂纹，尾部有熔岩球，螯肢巨大带火尖，八足爬行。
