【弱点】水属性可冷却熔岩，冰属性可冻结其外壳使其脆弱。', '[{"item_id": "mh-h2-N", "name": "三阶火/土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-380", "name": "熔岩壳片", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}, {"item_id": "cl-485", "name": "蝎尾火囊", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-254', '风雷雕', '魔兽', 40, 30, 38, 35, '风/雷', '【外观】羽毛银灰色带蓝紫色电纹，双翼巨大，喙如铁钩，目光锐利。
【体型】体长2.5米，翼展7米，肩高1.5米
