【弱点】火属性斗气可融化其冰甲，使移动速度降低。', '[{"item_id": "mh-h3-5", "name": "三阶冰属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-158", "name": "冰角×1，冰鳞片×8", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-257', '狂风枭', '魔兽', 28, 21, 27, 24, '风', '【外观】羽毛呈灰白色，双翼展开时有隐隐风纹流转，头部两侧长有三根翎羽如刀刃般锋利，瞳孔青白。
