INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-259', '雷隼鹫', '魔兽', 28, 21, 27, 24, '雷', '【外观】通体深蓝羽毛，颈部有亮银色雷纹，喙如钩状闪烁着电光，双爪缠有细微电弧，鸣叫声如雷声轰鸣。
