INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-260', '暗影豹', '魔兽', 28, 21, 27, 24, '暗', '【外观】通体黑毛如夜，无任何花纹，眼睛呈暗紫色，行动时身体边缘会扭曲光线，如影子般模糊。
