INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-261', '毒涎蛛', '魔兽', 28, 21, 27, 24, '毒', '【外观】腹部呈紫黑色，上有绿色毒纹斑点，八足细长覆有倒刺，口器旁伸出两根透明毒牙，吐丝时带绿色雾气。
