INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-262', '木灵鹿', '魔兽', 28, 21, 27, 24, '木', '【外观】通体翠绿色皮毛，鹿角由藤蔓交织而成，开有翠色嫩叶，蹄子如木质，眼瞳碧绿，身上散发淡淡草木清香。
