INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-263', '水纹蛟', '魔兽', 28, 21, 27, 24, '水', '【外观】体表覆盖淡蓝色细鳞，鳞片边缘如水流波动，头生独角尖锐如矛，腹部有白色纹路，游动时如透明在水中。
