INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-264', '赤焰蝎', '魔兽', 28, 21, 27, 24, '火', '【外观】通体赤红色硬甲，双钳巨大呈锯齿状，尾钩如红宝石般晶莹，内有熔岩般流动的毒液。
