【弱点】水属性斗气可冷却其体内高温，削弱其行动力。', '[{"item_id": "mh-h3-1", "name": "三阶火属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-505", "name": "赤蝎钳×2，毒囊×1", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-265', '冰晶蝶', '魔兽', 28, 21, 27, 24, '冰', '【外观】双翼薄如冰片，呈六角霜花结构，通体透明泛蓝光，触须如冰丝细长，飞行时洒落细碎冰晶。
