INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-266', '风翼虎', '魔兽', 28, 21, 27, 24, '风', '【外观】通体银白色条纹虎皮，背部生有一对半透明风翼，风翼边缘锋利如刀，虎目青芒闪烁，咆哮声如狂风呼啸。
【体型】体长3米，肩高1.4米，翼展5米
【核心能力】风翼斩：双翼挥出巨大风刃，可切开巨石；狂风吐息：喷出龙卷风气流，将目标吹飞20米远。
【弱点】土属性斗气可稳定身形，使其狂风吐息效果减半。', '[{"item_id": "mh-h3-3", "name": "三阶风属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-611", "name": "风翼膜×2，虎爪×4", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-267', '碎石猿', '魔兽', 28, 21, 27, 24, '土', '【外观】浑身灰褐色硬皮，双臂粗壮如石柱，拳头表面岩化呈不规则状，额头有凸起骨冠，吼声沉闷如滚石。
