【弱点】敏捷度低，可利用速度优势游击攻击。', '[{"item_id": "mh-h3-6", "name": "三阶土属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-421", "name": "石猿拳骨×2，硬皮块×4", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-268', '雷纹熊', '魔兽', 28, 21, 27, 24, '雷', '【外观】浑身棕色厚毛，背部有银色闪电状纹路，四爪粗大带有电弧，胸口的雷纹会随呼吸明灭闪亮。
