【弱点】水属性斗气可导电，反而能增强其攻击，建议用土属性。', '[{"item_id": "mh-h3-4", "name": "三阶雷属性魔核", "rate": 0.5, "min": 1, "max": 1, "type": "公共"}, {"item_id": "cl-537", "name": "雷纹毛皮×1，雷熊掌×4", "rate": 0.75, "min": 1, "max": 3, "type": "专属"}]');
INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-269', '暗蝠群', '魔兽', 28, 21, 27, 24, '暗', '【外观】每只蝙蝠体长仅0.3米，黑色皮膜翼，眼睛已退化，发出人耳不可闻的超声波定位，成群时如黑雾般笼罩。
