INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-270', '毒蔓蛇', '魔兽', 28, 21, 27, 24, '毒', '【外观】浑身翠绿色鳞片，头部呈三角形，毒牙可伸缩，鳞片间渗有绿色粘液，身体盘绕时如一根藤蔓，难以分辨。
