INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-271', '木甲蚁', '魔兽', 28, 21, 27, 24, '木', '【外观】体表覆盖木质铠甲般的硬壳，呈棕褐色，头部长有大颚如锯齿，触角末端有绿色光点，六足如尖刺。
