INSERT INTO mob (mob_id, name, type, power, intelligence, quick, stamina, attribute, description, drops) VALUES ('WB-273', '烈风雕', '魔兽', 28, 21, 27, 24, '风', '【外观】羽毛呈灰金色，双翼边缘镶有淡青色风系纹路，喙如精铁钩状，双眼锐利如鹰，飞行时身后拖着风尾。
